<template><div v-if="rows.length" class="table-scroll"><table v-table class="admin-table "><caption class="sr-only">领用及归还按件流水，名称为历史记录</caption><thead><tr><th data-width="210">办理号</th><th data-width="90">动作</th><th data-width="180">人员姓名</th><th data-width="160">人员编号</th><th data-width="160">设备编号</th><th data-width="180">设备名称</th><th data-width="120">设备类型</th><th data-width="140">经办人</th><th data-width="210">办理时间（UTC）</th><th data-width="210">领用开始（UTC）</th><th data-width="120">归还结果</th><th data-width="200">维修单</th></tr></thead><tbody><tr v-for="h in rows" :key="h.id"><td>{{ h.batchId }}</td><td>{{ h.action === 'ISSUE' ? '领用' : '归还' }}</td><td>{{ h.personName || '未知或无权查看' }}</td><td>{{ h.personCode || '—' }}</td><td>{{ h.deviceCode || '未知' }}</td><td>{{ h.deviceName || '—' }}</td><td>{{ DEVICE_TYPES[h.type] || '类型未知' }}</td><td>{{ h.actorName || '未知' }}</td><td>{{ utcTime(h.occurredAt) }}</td><td>{{ utcTime(h.startedAt) }}</td><td>{{ h.condition === 'GOOD' ? '完好' : h.condition === 'REPAIR' ? '需检修' : '—' }}</td><td><router-link v-if="h.maintenanceOrderId" :to="{ path: '/admin/assets/maintenance/' + h.maintenanceOrderId, query: { siteId: store.siteId, returnTo } }">{{ h.maintenanceOrderId }}</router-link><span v-else>—</span></td></tr></tbody></table></div><p v-else class="query-state">暂无符合条件的流水，初始绑定不补造历史。</p></template>
<script setup>
import { utcTime } from '../tablePresentation'
import { DEVICE_TYPES } from '../deviceData'
import { useAdminStore } from '../store'
defineProps({ rows: { type: Array, default: () => [] }, returnTo: { type: String, default: '/admin/assets/assignments?tab=history' } })
const store = useAdminStore()
</script>
